Object.assign(HELP_META, { rs_cady: [], rs_scp: [], rs_l1l2: [], rs_xphy: [], rs_aap: [], rs_rf: [] });
Object.assign(I18N.strings.en, {"help.rs_cady": "Clock module: a 60 MHz clock that drives the antenna’s beamforming chips and the main processor. Newer dishes (rev4, Mini) have no separate clock module, so “not ready” is normal on them.", "help.rs_scp": "Internal processor subsystem — most likely the secure processor that holds the dish’s identity and encryption keys.", "help.rs_l1l2": "Layers 1 and 2 of the satellite link: the physical radio link and the data-link layer that schedules and carries traffic to the satellites.", "help.rs_xphy": "Most likely the physical-layer (PHY) modem that converts data to and from the satellite radio signal.", "help.rs_aap": "Antenna array check: shows “not ready” when one of the digital beamforming chips in the antenna doesn’t respond.", "help.rs_rf": "Radio front end: the beamforming chips, their front-end amplifiers and power supply. “Not ready” usually points to a hardware or power fault in the antenna."});
Object.assign(I18N.strings.uk, {"help.rs_cady": "Модуль тактування: генератор 60 МГц, що живить чипи формування променя та головний процесор. У новіших антенах (rev4, Mini) окремого модуля немає, тож «не готово» для них — норма.", "help.rs_scp": "Внутрішня процесорна підсистема — найімовірніше, захищений процесор, що зберігає ідентифікатор антени та ключі шифрування.", "help.rs_l1l2": "Рівні 1 і 2 супутникового зв’язку: фізичний радіоканал і канальний рівень, що планує та передає трафік до супутників.", "help.rs_xphy": "Найімовірніше, модем фізичного рівня (PHY), що перетворює дані на супутниковий радіосигнал і назад.", "help.rs_aap": "Перевірка антенної решітки: показує «не готово», якщо один із цифрових чипів формування променя не відповідає.", "help.rs_rf": "Радіочастина: чипи формування променя, їхні підсилювачі та живлення. «Не готово» зазвичай вказує на апаратну несправність або проблему з живленням в антені."});
Object.assign(I18N.strings.es, {"help.rs_cady": "Módulo de reloj: un reloj de 60 MHz que alimenta los chips de conformación de haz y el procesador principal. Las antenas más nuevas (rev4, Mini) no tienen un módulo de reloj separado, así que «no listo» es normal en ellas.", "help.rs_scp": "Subsistema de procesador interno: muy probablemente el procesador seguro que guarda la identidad de la antena y sus claves de cifrado.", "help.rs_l1l2": "Capas 1 y 2 del enlace satelital: el enlace de radio físico y la capa de enlace de datos que programa y transporta el tráfico hacia los satélites.", "help.rs_xphy": "Muy probablemente el módem de capa física (PHY) que convierte los datos en la señal de radio del satélite y viceversa.", "help.rs_aap": "Comprobación de la matriz de antenas: muestra «no listo» cuando uno de los chips digitales de conformación de haz no responde.", "help.rs_rf": "Etapa de radio: los chips de conformación de haz, sus amplificadores y su alimentación. «No listo» suele indicar un fallo de hardware o de alimentación en la antena."});
Object.assign(I18N.strings.de, {"help.rs_cady": "Taktmodul: ein 60-MHz-Takt für die Beamforming-Chips der Antenne und den Hauptprozessor. Neuere Antennen (rev4, Mini) haben kein separates Taktmodul, daher ist „nicht bereit“ bei ihnen normal.", "help.rs_scp": "Internes Prozessor-Subsystem – höchstwahrscheinlich der Sicherheitsprozessor, der Kennung und Schlüssel der Antenne speichert.", "help.rs_l1l2": "Schicht 1 und 2 der Satellitenverbindung: die physische Funkstrecke und die Sicherungsschicht, die den Verkehr zu den Satelliten plant und überträgt.", "help.rs_xphy": "Höchstwahrscheinlich das Modem der Bitübertragungsschicht (PHY), das Daten in das Satellitenfunksignal umwandelt und zurück.", "help.rs_aap": "Prüfung des Antennenfelds: zeigt „nicht bereit“, wenn einer der digitalen Beamforming-Chips der Antenne nicht antwortet.", "help.rs_rf": "Funk-Frontend: die Beamforming-Chips, ihre Verstärker und ihre Stromversorgung. „Nicht bereit“ deutet meist auf einen Hardware- oder Stromversorgungsfehler in der Antenne hin."});
Object.assign(I18N.strings.fr, {"help.rs_cady": "Module d’horloge : une horloge de 60 MHz qui cadence les puces de formation de faisceau et le processeur principal. Les antennes récentes (rev4, Mini) n’ont plus de module d’horloge séparé, « pas prêt » y est donc normal.", "help.rs_scp": "Sous-système processeur interne — très probablement le processeur sécurisé qui conserve l’identité et les clés de chiffrement de l’antenne.", "help.rs_l1l2": "Couches 1 et 2 de la liaison satellite : la liaison radio physique et la couche liaison de données qui planifie et transporte le trafic vers les satellites.", "help.rs_xphy": "Très probablement le modem de couche physique (PHY) qui convertit les données en signal radio satellite et inversement.", "help.rs_aap": "Contrôle du réseau d’antennes : affiche « pas prêt » lorsqu’une des puces numériques de formation de faisceau ne répond pas.", "help.rs_rf": "Étage radio : les puces de formation de faisceau, leurs amplificateurs et leur alimentation. « Pas prêt » indique généralement une panne matérielle ou d’alimentation dans l’antenne."});
Object.assign(I18N.strings.pt, {"help.rs_cady": "Módulo de clock: um clock de 60 MHz que alimenta os chips de formação de feixe e o processador principal. Antenas mais novas (rev4, Mini) não têm módulo de clock separado, então “não pronto” é normal nelas.", "help.rs_scp": "Subsistema de processador interno — muito provavelmente o processador seguro que guarda a identidade e as chaves de criptografia da antena.", "help.rs_l1l2": "Camadas 1 e 2 do link via satélite: o link de rádio físico e a camada de enlace de dados que agenda e transporta o tráfego até os satélites.", "help.rs_xphy": "Muito provavelmente o modem de camada física (PHY) que converte dados no sinal de rádio do satélite e vice-versa.", "help.rs_aap": "Verificação da matriz de antenas: mostra “não pronto” quando um dos chips digitais de formação de feixe não responde.", "help.rs_rf": "Estágio de rádio: os chips de formação de feixe, seus amplificadores e a alimentação. “Não pronto” geralmente indica falha de hardware ou de alimentação na antena."});
Object.assign(I18N.strings.it, {"help.rs_cady": "Modulo di clock: un clock a 60 MHz che pilota i chip di beamforming e il processore principale. Le antenne più recenti (rev4, Mini) non hanno un modulo di clock separato, quindi “non pronto” è normale.", "help.rs_scp": "Sottosistema processore interno: molto probabilmente il processore sicuro che conserva l’identità e le chiavi di cifratura dell’antenna.", "help.rs_l1l2": "Livelli 1 e 2 del collegamento satellitare: il collegamento radio fisico e il livello di collegamento dati che pianifica e trasporta il traffico verso i satelliti.", "help.rs_xphy": "Molto probabilmente il modem di livello fisico (PHY) che converte i dati nel segnale radio satellitare e viceversa.", "help.rs_aap": "Controllo della schiera di antenne: mostra “non pronto” quando uno dei chip digitali di beamforming non risponde.", "help.rs_rf": "Stadio radio: i chip di beamforming, i loro amplificatori e l’alimentazione. “Non pronto” indica di solito un guasto hardware o di alimentazione nell’antenna."});
Object.assign(I18N.strings.pl, {"help.rs_cady": "Moduł zegara: generator 60 MHz taktujący układy kształtowania wiązki i główny procesor. Nowsze anteny (rev4, Mini) nie mają osobnego modułu zegara, więc „niegotowe” jest u nich normalne.", "help.rs_scp": "Wewnętrzny podsystem procesora — najpewniej bezpieczny procesor przechowujący tożsamość anteny i klucze szyfrowania.", "help.rs_l1l2": "Warstwy 1 i 2 łącza satelitarnego: fizyczne łącze radiowe i warstwa łącza danych, która planuje i przesyła ruch do satelitów.", "help.rs_xphy": "Najpewniej modem warstwy fizycznej (PHY), który zamienia dane na satelitarny sygnał radiowy i z powrotem.", "help.rs_aap": "Kontrola szyku antenowego: pokazuje „niegotowe”, gdy jeden z cyfrowych układów kształtowania wiązki nie odpowiada.", "help.rs_rf": "Tor radiowy: układy kształtowania wiązki, ich wzmacniacze i zasilanie. „Niegotowe” zwykle oznacza usterkę sprzętu lub zasilania w antenie."});
Object.assign(I18N.strings.zh, {"help.rs_cady": "时钟模块：为天线波束成形芯片和主处理器提供 60 MHz 时钟。较新的天线（rev4、Mini）已没有独立的时钟模块，因此显示“未就绪”属正常。", "help.rs_scp": "内部处理器子系统——很可能是保存天线身份和加密密钥的安全处理器。", "help.rs_l1l2": "卫星链路的第 1 层和第 2 层：物理无线链路，以及负责调度并向卫星传送流量的数据链路层。", "help.rs_xphy": "很可能是物理层（PHY）调制解调器，负责在数据与卫星无线信号之间相互转换。", "help.rs_aap": "天线阵列检查：当天线中某个数字波束成形芯片无响应时显示“未就绪”。", "help.rs_rf": "射频前端：波束成形芯片及其放大器和供电。“未就绪”通常表示天线内部存在硬件或供电故障。"});
Object.assign(I18N.strings.ja, {"help.rs_cady": "クロックモジュール：アンテナのビームフォーミングチップとメインプロセッサに 60 MHz のクロックを供給します。新しいアンテナ（rev4、Mini）には独立したクロックモジュールがないため、「未準備」でも正常です。", "help.rs_scp": "内部プロセッサのサブシステム。アンテナの ID と暗号鍵を保持するセキュアプロセッサである可能性が高いです。", "help.rs_l1l2": "衛星リンクのレイヤー 1 と 2：物理的な無線リンクと、衛星への通信をスケジュールして運ぶデータリンク層です。", "help.rs_xphy": "データと衛星の無線信号を相互に変換する物理層（PHY）モデムである可能性が高いです。", "help.rs_aap": "アンテナアレイのチェック：アンテナ内のデジタルビームフォーミングチップのいずれかが応答しないと「未準備」になります。", "help.rs_rf": "無線フロントエンド：ビームフォーミングチップとそのアンプ、電源です。「未準備」は通常、アンテナ内のハードウェアまたは電源の故障を示します。"});
